    void update() override;
protected:
    virtual double compute() const = 0;
private:
    mutable std::atomic<bool> dirty_{true};
    mutable std::atomic<long> computations_{0};
    mutable std::atomic<double> cached_value_{0.0};
    mutable std::mutex mutex_;
};

// Black-Scholes forward-free price model used by tests.
