#include "include/market.hpp"
#include <iostream>

// Simple test to verify the implementation works
class TestObserver : public mkt::Observer {
public:
    void update() override {
        std::cout << "Observer notified!" << std::endl;
    }
};

class TestEngine : public mkt::Engine {
public:
    double price(double spot, double strike, double vol) const override {
        return spot - strike + vol;
    }

    std::string name() const override {
        return "test";
    }
};

// Register an engine
REGISTER_ENGINE("test", TestEngine);

int main() {
    // Test Observer/Observable
    auto quote = std::make_shared<mkt::Quote>(100.0);
    auto observer = std::make_shared<TestObserver>();

    observer->observe(quote);
    quote->set(105.0);

    // Test LazyObject
    class TestLazyObject : public mkt::LazyObject {
    protected:
        double compute() const override {
            return 42.0;
        }
    };

    TestLazyObject lazy;
    std::cout << "Lazy object value: " << lazy.value() << std::endl;

    // Test Factory
    auto factory = &mkt::EngineFactory::instance();
    auto engine = factory->create("test");
    std::cout << "Engine name: " << engine->name() << std::endl;

    // Test MemoEngine
    mkt::MemoEngine memo(std::make_unique<TestEngine>());
    std::cout << "Memo engine price: " << memo.price(100.0, 90.0, 0.2) << std::endl;
    std::cout << "Memo engine name: " << memo.name() << std::endl;

    return 0;
}

